let prodBlocks = prods.map(p => {
    let rank = p.rank || 1;
    let title = p.title || ('Producto ' + rank);
    let priceStr = (p.price && p.price.toLowerCase() !== 'consultar en amazon') ? p.price : 'Consultar en Amazon (ver enlace)';
    let revCountStr = p.review_count ? (' (' + p.review_count + ')') : '';

    let specsList = [];
    if (p.specs && typeof p.specs === 'object') {
        specsList = Object.entries(p.specs).slice(0, 4).map(([k, v]) => k + ': ' + v);
    }
    let specsStr = specsList.length > 0 ? specsList.join(', ') : 'Materiales ergonómicos de alta durabilidad y resistencia';

    let featList = [];
    if (Array.isArray(p.features) && p.features.length > 0) {
        featList = p.features.slice(0, 2);
    } else if (p.description_snippet) {
        featList = [p.description_snippet.slice(0, 120)];
    } else {
