let projectDir = '';
try {
    projectDir = $('1b. Parsear Scraper').first().json.project_dir;
} catch (e1) {}

if (!projectDir) {
    try {
        projectDir = $('0b. Parsear Temática').first().json.project_dir;
    } catch (e2) {}
}

if (!projectDir) {
    try {
        projectDir = $input.first().json.project_dir;
    } catch (e3) {}
}

let containerDir = (projectDir || '').replace('/files', '/files');
let fs = require('fs');
// ============================================================================
// 🛡️ PRE-PUBLISH SANITY GATE (COMPROBACIÓN PREVENTIVA DE PUBLICACIÓN HORIZONTAL)
// ============================================================================
if (containerDir && fs.existsSync(containerDir)) {
    let gateErrors = [];
    const NICHE_BANNED = {
        'taller': ['barbacoa', 'parrilla', 'bbq', 'pelo', 'cabello', 'afeitad', 'afeitadora', 'cortapelo', 'depilad', 'barba', 'dientes', 'dental', 'cocina', 'vajilla', 'sarten', 'sartén', 'olla', 'aspirador', 'colchon', 'mascota', 'fregadero', 'inodoro', 'champú'],
        'barberia': ['madera', 'taller', 'taladro', 'sierra', 'bricolaje', 'jardin', 'cesped', 'cocina', 'sarten', 'freidora', 'aspirador', 'fregona', 'limpieza', 'coche'],
        'cocina': ['taladro', 'sierra', 'amoladora', 'taller', 'pelo', 'afeitad', 'zapato', 'zapatilla', 'aspiradora', 'fregona', 'soldador'],
        'limpieza': ['sarten', 'sartén', 'olla', 'cocina', 'taladro', 'sierra', 'zapato', 'zapatilla', 'libro', 'novela', 'barberia', 'afeitadora'],
        'zapateria': ['aspiradora', 'freidora', 'sartén', 'taladro', 'sierra', 'libro', 'novela', 'afeitadora'],
        'libreria': ['aspiradora', 'freidora', 'taladro', 'zapato', 'afeitadora', 'sarten', 'bateria de cocina']
    };

    let dirLow = containerDir.toLowerCase();
    let niche = 'general';
    if (dirLow.includes('taller') || dirLow.includes('bricolaje')) niche = 'taller';
    else if (dirLow.includes('barber') || dirLow.includes('afeitad')) niche = 'barberia';
    else if (dirLow.includes('cocina')) niche = 'cocina';
    else if (dirLow.includes('limpiez')) niche = 'limpieza';
    else if (dirLow.includes('zapat') || dirLow.includes('calzad')) niche = 'zapateria';
    else if (dirLow.includes('librer') || dirLow.includes('libro')) niche = 'libreria';

    let bannedList = NICHE_BANNED[niche] || [];

    // 1. Validación Semántica de Productos desde data.json
    let dataJsonPath = containerDir + '/data.json';
    if (fs.existsSync(dataJsonPath)) {
        try {
            let dRaw = JSON.parse(fs.readFileSync(dataJsonPath, 'utf8'));
            let qLow = (dRaw.query || '').toLowerCase();
            let prods = dRaw.products || [];
            if (!prods.length && dRaw.product_a && dRaw.product_b) {
                prods = [dRaw.product_a, dRaw.product_b];
            }
            for (let idx = 0; idx < prods.length; idx++) {
                let pTitle = (prods[idx].title || '').toLowerCase();
                for (let b of bannedList) {
                    let re = new RegExp('\\b' + b + '\\b', 'i');
                    if (re.test(pTitle) && !qLow.includes(b)) {
                        gateErrors.push(`[HORIZONTAL] Producto #${idx + 1} ajeno al nicho ${niche}: término prohibido '${b}' en '${prods[idx].title.substring(0, 45)}...'`);
                    }
                }
            }
        } catch (eData) {
            gateErrors.push(`Error analizando data.json: ${eData.message}`);
        }
    } else {
        gateErrors.push('data.json no existe en el directorio del proyecto.');
    }

    // 2. Validación de Vídeo Horizontal Renderizado
    let horizFiles = ['/RENDER_FINAL_AMAZON.mp4', '/RENDER_FINAL_NAS.mp4'];
    let videoFound = false;
    for (let hf of horizFiles) {
        let vPath = containerDir + hf;
        if (fs.existsSync(vPath)) {
            let stat = fs.statSync(vPath);
            if (stat.size > 1000000) {
                videoFound = true;
                break;
            }
        }
    }
    if (!videoFound) {
        gateErrors.push('[HORIZONTAL] Vídeo renderizado horizontal ausente o corrupto (< 1MB).');
    }

    // 3. Validación de Miniatura (solo si ya existe en disco)
    let thumbPath = containerDir + '/thumbnail.jpg';
    if (fs.existsSync(thumbPath)) {
        let tStat = fs.statSync(thumbPath);
        if (tStat.size < 30000) {
            gateErrors.push(`[MINIATURA] thumbnail.jpg demasiado ligera (${tStat.size} bytes).`);
        }
    }

    if (gateErrors.length > 0) {
        throw new Error('[PRE-PUBLISH GATE BLOQUEADO - HORIZONTAL] ' + gateErrors.join(' | '));
    }
}
let title = '';
let description = '';
let tags_str = '';
let pinned_comment = '';

// 1. Intentar desde nodo 'YT Parsear Metadatos'
try {
    let parsedNode = $('YT Parsear Metadatos').first().json;
    if (parsedNode.title) title = parsedNode.title;
    if (parsedNode.description) description = parsedNode.description;
    if (parsedNode.pinned_comment) pinned_comment = parsedNode.pinned_comment;
} catch(eNode) {}

// 2. Intentar desde nodo 'YT Preparar Input Ollama'
if (!title || !description || description.includes('[LINKS DE AFILIADO]') || description.includes('[Producto]')) {
    try {
        let ollamaInput = $('YT Preparar Input Ollama').first().json;
        if (!title && ollamaInput.current_title) title = ollamaInput.current_title;
        if (ollamaInput.current_description && ollamaInput.current_description.includes('http')) {
            description = ollamaInput.current_description;
        }
    } catch(eOllama) {}
}

// 3. Intentar desde youtube_metadata.json en disco
let metaFile = containerDir + '/youtube_metadata.json';
if (!pinned_comment && fs.existsSync(metaFile)) {
    try {
        let metaObj = JSON.parse(fs.readFileSync(metaFile, 'utf-8'));
        if (metaObj.pinned_comment) pinned_comment = metaObj.pinned_comment;
    } catch(ePin) {}
}
if ((!title || !description || description.includes('[LINKS DE AFILIADO]') || description.includes('[Producto]') || !tags_str) && fs.existsSync(metaFile)) {
    try {
        let meta = JSON.parse(fs.readFileSync(metaFile, 'utf-8'));
        if (!title) title = meta.youtube_title || meta.title || '';
        if (meta.youtube_description && meta.youtube_description.includes('http')) {
            description = meta.youtube_description;
        }
        if (!tags_str) tags_str = meta.tags_str || (meta.tags ? meta.tags.join(',') : '');
        if (meta.pinned_comment) pinned_comment = meta.pinned_comment;
    } catch(eFile) {}
}

// 4. Intentar desde youtube_metadata.txt en disco si la descripción sigue sin ser válida
let txtFile = containerDir + '/youtube_metadata.txt';
if ((!description || description.includes('[LINKS DE AFILIADO]') || description.includes('[Producto]') || !description.includes('http')) && fs.existsSync(txtFile)) {
    try {
        let txtContent = fs.readFileSync(txtFile, 'utf-8');
        if (txtContent.includes('DESCRIPCIÓN DE YOUTUBE')) {
            description = txtContent.split('DESCRIPCIÓN DE YOUTUBE')[1].replace(/═+/g, '').trim();
        } else if (txtContent.includes('DESCRIPCIÓN:')) {
            description = txtContent.split('DESCRIPCIÓN:')[1].trim();
        } else {
            description = txtContent.trim();
        }
    } catch(eTxt) {}
}

// 5. Fallback tags_str desde nodo de etiquetas o input
if (!tags_str) {
    try {
        let tagsNode = $('YT Generador de Tags SEO').first().json;
        if (tagsNode.stdout) {
            let tObj = JSON.parse(tagsNode.stdout);
            tags_str = tObj.tags_str || '';
        }
    } catch(eT) {}
}

// 6. Generación de título de respaldo
if (!title || title.endsWith('...') || title.length < 15 || title.includes('_')) {
    try {
        let scraper = $('1b. Parsear Scraper').first().json || {};
        let productA = scraper.product_a || {};
        let productB = scraper.product_b || {};
        let brandA = (productA.brand || '').toUpperCase().trim();
        let brandB = (productB.brand || '').toUpperCase().trim();
        let q = (scraper.query || (scraper.search_query || '')).replace(/_/g, ' ').trim();
        if (brandA && brandB && brandA !== brandB) {
            title = brandA + ' vs ' + brandB + (q ? ' | ' + q.charAt(0).toUpperCase() + q.slice(1) : '') + ' ¿Cuál Elegir?';
        } else if (q) {
            title = 'TOP COMPARATIVA | ' + q.charAt(0).toUpperCase() + q.slice(1) + ' 2026 ⚔️';
        }
    } catch(e5) {}
}
if (!title || title.length < 10) {
    title = 'Comparativa de Productos 2026 ⚔️';
}

title = title.replace(/_/g, ' ').replace(/\s+/g, ' ').trim();
if (title.length > 95) {
    title = title.substring(0, 92).trim();
}

if (description) {
    description = description.replace(/_/g, ' ').trim();
}

const items = $input.all();
const outItems = [];
for (let item of items) {
    let newItem = {
        json: {
            ...item.json,
            title: title,
            description: description,
            tags_str: tags_str,
            pinned_comment: pinned_comment
        }
    };
    if (item.binary) newItem.binary = item.binary;
    outItems.push(newItem);
}
return outItems;

if (tags_str) {
    let tagArr = tags_str.split(',');
    let safeTags = [];
    let curLen = 0;
    for (let t of tagArr) {
        let tClean = t.trim();
        if (!tClean) continue;
        let tLen = tClean.length + (tClean.includes(' ') ? 2 : 0) + (safeTags.length ? 1 : 0);
        if (curLen + tLen > 380) break;
        safeTags.push(tClean);
        curLen += tLen;
    }
    tags_str = safeTags.join(',');
}

let stdoutStr = $json.stdout || '';
let data = {};
